export default function PaymentTrackingPourSuperadmin() {
  const [searchQuery, setSearchQuery] = useState("")
  const [payments, setPayments] = useState([])
  const [isLoading, setIsLoading] = useState(true)
  const [error, setError] = useState("")
  const [sortField, setSortField] = useState("internId.First_Name")
  const [sortDirection, setSortDirection] = useState("asc")
  const [isPaymentModalOpen, setIsPaymentModalOpen] = useState(false)
  const [selectedPayment, setSelectedPayment] = useState(null)
  const [selectedMonths, setSelectedMonths] = useState([])
  const [paymentAmount, setPaymentAmount] = useState(200)
  const [isDetailsModalOpen, setIsDetailsModalOpen] = useState(false)
  const [detailsPayment, setDetailsPayment] = useState(null)

  useEffect(() => {
    fetchPayments()
  }, [])

  const fetchPayments = async () => {
    setIsLoading(true)
    setError("")
    const token = localStorage.getItem("token")

    if (!token) {
      setError("Authentication required. Please log in.")
      setIsLoading(false)
      return
    }

    try {
      const response = await axios.get(`${process.env.REACT_APP_API_URL}/api/payments`, {
        headers: {
          Authorization: `Bearer ${token}`,
          Role: "Deputydirector",
        },
      })
      if (response.data.success) {
        setPayments(response.data.data)
      } else {
        setError("Failed to fetch payments: " + response.data.message)
      }
    } catch (err) {
      setError(`Error fetching payments: ${err.response?.data?.message || err.message}`)
      /* eslint-disable */console.error(...oo_tx(`429881422_69_6_69_49_11`,"Fetch payments error:", err))
    } finally {
      setIsLoading(false)
    }
  }

  const handleSort = (field) => {
    if (sortField === field) {
      setSortDirection(sortDirection === "asc" ? "desc" : "asc")
    } else {
      setSortField(field)
      setSortDirection("asc")
    }
  }

  const openPaymentModal = (payment) => {
    setSelectedPayment(payment)
    const paidMonths = Object.keys(payment.payments).filter((month) => payment.payments[month] > 0)
    setSelectedMonths(paidMonths)
    setPaymentAmount(200)
    setIsPaymentModalOpen(true)
  }

  const closePaymentModal = () => {
    setIsPaymentModalOpen(false)
    setSelectedPayment(null)
  }

  const openDetailsModal = (payment) => {
    setDetailsPayment(payment)
    setIsDetailsModalOpen(true)
  }

  const closeDetailsModal = () => {
    setIsDetailsModalOpen(false)
    setDetailsPayment(null)
  }

  const monthTranslations = {
    September: "Septembre",
    October: "Octobre",
    November: "Novembre",
    December: "Décembre",
    January: "Janvier",
    February: "Février",
    March: "Mars",
    April: "Avril",
    May: "Mai",
    June: "Juin",
    July: "Juillet",
    August: "Août",
  }

  const generateReceiptPDF = (intern, monthsPaid, amount) => {
    const doc = new jsPDF()
    const currentDate = new Date().toLocaleDateString("fr-FR")
    const pageWidth = doc.internal.pageSize.getWidth()
    const margin = 15
    const maxWidth = pageWidth - 2 * margin

    doc.setFillColor(245, 245, 245)
    doc.rect(0, 0, pageWidth, 40, "F")
    doc.setFontSize(20)
    doc.setFont("helvetica", "bold")
    doc.setTextColor(33, 37, 41)
    doc.text("Reçu de Paiement", pageWidth / 2, 25, { align: "center" })
    doc.setLineWidth(0.5)
    doc.setDrawColor(200, 200, 200)
    doc.line(margin, 40, pageWidth - margin, 40)

    doc.setFontSize(10)
    doc.setFont("helvetica", "normal")
    doc.setTextColor(100, 100, 100)
    doc.text("HP ISTA Benguérir", pageWidth / 2, 50, { align: "center" })
    doc.text("Hôtel Pédagogique ISTA Benguérir", pageWidth / 2, 57, { align: "center" })
    doc.text("Email: contact@example.com | Téléphone: +212 234 567 890", pageWidth / 2, 64, { align: "center" })

    doc.setFontSize(14)
    doc.setFont("helvetica", "bold")
    doc.setTextColor(33, 37, 41)
    doc.text("Détails du Stagiaire", margin, 80)
    doc.setFontSize(11)
    doc.setFont("helvetica", "normal")
    doc.text(`Nom: ${intern.internId.First_Name} ${intern.internId.Last_Name}`, margin, 90, { maxWidth })
    doc.text(`CFF: ${intern.internId.CFF}`, margin, 97, { maxWidth })
    doc.text(`Année Académique: ${intern.academicYear}`, margin, 104, { maxWidth })
    doc.setLineWidth(0.2)
    doc.setDrawColor(230, 230, 230)
    doc.line(margin, 110, pageWidth - margin, 110)

    doc.setFontSize(14)
    doc.setFont("helvetica", "bold")
    doc.text("Détails du Paiement", margin, 125)
    doc.setFontSize(11)
    doc.setFont("helvetica", "normal")

    doc.setFillColor(230, 230, 230)
    doc.rect(margin, 135, maxWidth, 10, "F")
    doc.setTextColor(33, 37, 41)
    doc.text("Mois", margin + 5, 142)
    doc.text("Montant (DH)", pageWidth - margin - 40, 142, { align: "right" })
    doc.setLineWidth(0.1)
    doc.line(margin, 145, pageWidth - margin, 145)

    let yPos = 155
    monthsPaid.forEach((month) => {
      doc.text(monthTranslations[month], margin + 5, yPos)
      doc.text(`${amount.toFixed(2)}`, pageWidth - margin - 40, yPos, { align: "right" })
      doc.line(margin, yPos + 5, pageWidth - margin, yPos + 5)
      yPos += 12
    })

    doc.setFontSize(12)
    doc.setFont("helvetica", "bold")
    doc.text("Montant Total", margin + 5, yPos + 10)
    doc.setFont("helvetica", "normal")
    doc.text(`${(amount * monthsPaid.length).toFixed(2)} DH`, pageWidth - margin - 40, yPos + 10, { align: "right" })
    doc.setLineWidth(0.3)
    doc.line(margin, yPos + 15, pageWidth - margin, yPos + 15)

    doc.setFontSize(9)
    doc.setTextColor(100, 100, 100)
    doc.text("Merci pour votre paiement!", pageWidth / 2, pageWidth - 20, { align: "center" })
    doc.setLineWidth(0.5)
    doc.setDrawColor(200, 200, 200)
    doc.line(margin, pageWidth - 30, pageWidth - margin, pageWidth - 30)

    doc.save(`Reçu_${intern.internId.First_Name}_${intern.internId.Last_Name}_${currentDate}.pdf`)
  }

const exportDetailsToPDF = (payment) => {
    // Define all 12 months including August
    const months = [
      "September", "October", "November", "December", 
      "January", "February", "March", "April", 
      "May", "June", "July", "August"
    ];

    const monthTranslations = {
      "September": "Septembre",
      "October": "Octobre",
      "November": "Novembre",
      "December": "Décembre",
      "January": "Janvier",
      "February": "Février",
      "March": "Mars",
      "April": "Avril",
      "May": "Mai",
      "June": "Juin",
      "July": "Juillet",
      "August": "Août"
    };

    const doc = new jsPDF()
    const currentDate = new Date().toLocaleDateString("fr-FR")
    const pageWidth = doc.internal.pageSize.getWidth()
    const margin = 15
    const maxWidth = pageWidth - 2 * margin

    doc.setFillColor(245, 245, 245)
    doc.rect(0, 0, pageWidth, 40, "F")
    doc.setFontSize(20)
    doc.setFont("helvetica", "bold")
    doc.setTextColor(33, 37, 41)
    doc.text("Détails des Paiements", pageWidth / 2, 25, { align: "center" })
    doc.setLineWidth(0.5)
    doc.setDrawColor(200, 200, 200)
    doc.line(margin, 40, pageWidth - margin, 40)

    // Removed the HP ISTA Benguérir contact information section

    doc.setFontSize(14)
    doc.setFont("helvetica", "bold")
    doc.setTextColor(33, 37, 41)
    doc.text("Informations du Stagiaire", margin, 60) // Adjusted y-position from 80 to 60
    doc.setFontSize(11)
    doc.setFont("helvetica", "normal")
    doc.text(`Nom: ${payment.internId.First_Name} ${payment.internId.Last_Name}`, margin, 70, { maxWidth }) // Adjusted y-positions
    doc.text(`CFF: ${payment.internId.CFF}`, margin, 77, { maxWidth })
    doc.text(`Année Académique: ${payment.academicYear}`, margin, 84, { maxWidth })
    doc.text(`Total Payé: ${payment.totalAmount} DH`, margin, 91, { maxWidth })
    doc.text(
      `Mois Payés: ${Object.keys(payment.payments).filter((month) => payment.payments[month] >= 0).length}/${
        months.length
      }`,
      margin,
      98,
      { maxWidth }
    )
    doc.setLineWidth(0.2)
    doc.setDrawColor(230, 230, 230)
    doc.line(margin, 105, pageWidth - margin, 105) // Adjusted y-position

    doc.setFontSize(14)
    doc.setFont("helvetica", "bold")
    doc.text("Historique des Paiements", margin, 120) // Adjusted y-position
    doc.setFontSize(11)
    doc.setFont("helvetica", "normal")

    doc.setFillColor(230, 230, 230)
    doc.rect(margin, 130, maxWidth, 10, "F") // Adjusted y-position
    doc.setTextColor(33, 37, 41)
    doc.text("Mois", margin + 5, 137) // Adjusted y-position
    doc.text("Montant (DH)", margin + 80, 137)
    doc.text("Statut", margin + 130, 137)
    doc.setLineWidth(0.1)
    doc.line(margin, 140, pageWidth - margin, 140) // Adjusted y-position

    let yPos = 150 // Adjusted starting y-position
    months.forEach((month) => {
      const isPaid = payment.payments[month] > 0
      doc.text(monthTranslations[month], margin + 5, yPos)
      doc.text(isPaid ? `${payment.payments[month].toFixed(2)}` : "-", margin + 80, yPos)
      doc.text(isPaid ? "Payé" : "En Attente", margin + 130, yPos)
      doc.line(margin, yPos + 5, pageWidth - margin, yPos + 5)
      yPos += 12
    })

    if (payment.observation) {
      doc.setFontSize(14)
      doc.setFont("helvetica", "bold")
      doc.text("Observation", margin, yPos + 15)
      doc.setFontSize(11)
      doc.setFont("helvetica", "normal")
      doc.text(payment.observation, margin, yPos + 25, { maxWidth })
      yPos += 35
    }

    doc.setFontSize(9)
    doc.setTextColor(100, 100, 100)
    doc.text(`Date Actuelle: ${currentDate}`, margin, yPos + 20, { maxWidth })
    doc.text(`Créé: ${new Date(payment.createdAt).toLocaleString("fr-FR")}`, margin, yPos + 27, { maxWidth })
    doc.text(`Mis à jour: ${new Date(payment.updatedAt).toLocaleString("fr-FR")}`, margin, yPos + 34, { maxWidth })
    doc.text(`Exporté le: ${currentDate}`, margin, yPos + 41, { maxWidth })
    doc.text("Généré par le Système de Suivi des Paiements", pageWidth / 2, yPos + 48, { align: "center" })
    doc.setLineWidth(0.5)
    doc.setDrawColor(200, 200, 200)
    doc.line(margin, yPos + 10, pageWidth - margin, yPos + 10)

    doc.save(`Détails_Paiements_${payment.internId.First_Name}_${payment.internId.Last_Name}_${currentDate}.pdf`)
}

  const handleConfirmPayment = async () => {
    if (selectedMonths.length === 0) {
      setError("Veuillez sélectionner au moins un mois à marquer comme payé.")
      return
    }

    try {
      const token = localStorage.getItem("token")
      const response = await axios.patch(
        `${process.env.REACT_APP_API_URL}/api/payments/${selectedPayment.internId._id}`,
        {
          months: selectedMonths,
          amount: paymentAmount,
        },
        {
          headers: {
            Authorization: `Bearer ${token}`,
            Role: "Deputydirector",
          },
        }
      )

      if (response.data.success) {
        fetchPayments()
        const newPaidMonths = selectedMonths.filter(
          (month) => !Object.keys(selectedPayment.payments).includes(month) || selectedPayment.payments[month] === 0
        )
        if (newPaidMonths.length > 0) {
          generateReceiptPDF(selectedPayment, newPaidMonths, paymentAmount)
        }
        closePaymentModal()
      }
    } catch (err) {
      setError("Échec de la mise à jour du paiement: " + (err.response?.data?.message || err.message))
    }
  }

  const filteredAndSortedPayments = payments
    .filter((payment) => {
      if (!payment.internId) return false
      const matchesSearch =
        `${payment.internId.First_Name} ${payment.internId.Last_Name}`
          .toLowerCase()
          .includes(searchQuery.toLowerCase()) || payment.internId.CFF.toLowerCase().includes(searchQuery.toLowerCase())
      return matchesSearch
    })
    .sort((a, b) => {
      if (sortField.includes("internId")) {
        const [parent, child] = sortField.split(".")
        const valueA = a[parent]?.[child]?.toString().toLowerCase() || ""
        const valueB = b[parent]?.[child]?.toString().toLowerCase() || ""
        return sortDirection === "asc" ? valueA.localeCompare(valueB) : valueB.localeCompare(valueA)
      }
      const valueA = a[sortField]?.toString().toLowerCase() || ""
      const valueB = b[sortField]?.toString().toLowerCase() || ""
      return sortDirection === "asc" ? valueA.localeCompare(valueB) : valueB.localeCompare(valueA)
    })

  const handleExportToExcel = () => {
    const exportData = filteredAndSortedPayments.map((payment) => ({
      CFF: payment.internId.CFF,
      "Prénom": payment.internId.First_Name,
      "Nom": payment.internId.Last_Name,
      "Année Académique": payment.academicYear,
      ...Object.fromEntries(
        Object.entries(payment.payments).map(([month, amount]) => [monthTranslations[month], amount])
      ),
      "Montant Total": payment.totalAmount,
      Observation: payment.observation || "",
      "Créé le": new Date(payment.createdAt).toLocaleString("fr-FR"),
      "Mis à jour le": new Date(payment.updatedAt).toLocaleString("fr-FR"),
    }))

    const ws = XLSX.utils.json_to_sheet(exportData)
    const wb = XLSX.utils.book_new()
    XLSX.utils.book_append_sheet(wb, ws, "Paiements")
    XLSX.writeFile(wb, "Suivi_Paiements_Export.xlsx")
  }

  const getSortIcon = (field) => {
    if (sortField !== field) return null
    return sortDirection === "asc" ? <ChevronUp className="h-4 w-4" /> : <ChevronDown className="h-4 w-4" />
  }

  const months = [
    "September",
    "October",
    "November",
    "December",
    "January",
    "February",
    "March",
    "April",
    "May",
    "June",
    "July",
    "August",
  ]

  const getPaymentProgress = (payment) => {
    const paidMonths = Object.keys(payment.payments).filter((month) => payment.payments[month] > 0).length
    return (paidMonths / months.length) * 100
  }

  const getPaymentStatus = (payment) => {
    const paidMonths = Object.keys(payment.payments).filter((month) => payment.payments[month] > 0).length
    if (paidMonths === 0) return { label: "Non Commencé", color: "bg-red-100 text-red-800" }
    if (paidMonths === months.length) return { label: "Complet", color: "bg-green-100 text-green-800" }
    return { label: "En Cours", color: "bg-yellow-100 text-yellow-800" }
  }

  return (
    <Layout>
      <div className="max-w-7xl mx-auto">
        <div className="bg-white rounded-xl shadow-lg overflow-hidden border border-[#C8A45D/30]/50">
          <div className="bg-gradient-to-r from-[#00717F] to-[#C8A45D] text-white p-6">
            <div className="flex flex-col md:flex-row justify-between items-start md:items-center gap-4">
              <div>
                <h1 className="text-2xl font-bold tracking-tight">Suivi des Paiements</h1>
                <p className="text-white/80 mt-1">Suivre les statuts de paiement de tous les stagiaires</p>
              </div>
              <div className="flex items-center gap-2">
                <div className="bg-white/10 text-white text-sm px-3 py-1.5 rounded-md flex items-center gap-1.5">
                  <DollarSign className="h-4 w-4" />
                  <span>Nombre total de stagiaires: {payments.length}</span>
                </div>
              </div>
            </div>
          </div>

          <div className="p-6 border-b border-[#C8A45D/30]/50">
            <div className="flex flex-col md:flex-row gap-4">
              <div className="relative flex-1">
                <div className="absolute inset-y-0 left-0 pl-3 flex items-center pointer-events-none">
                  <Search className="h-5 w-5 text-gray-400" />
                </div>
                <input
                  className="w-full bg-white placeholder:text-gray-400 text-gray-900 text-sm border border-[#C8A45D/30] rounded-md pl-10 pr-3 py-2.5 shadow-sm focus:outline-none focus:ring-2 focus:ring-[#00717F]/50 focus:border-transparent transition-all"
                  placeholder="Rechercher par nom ou CFF..."
                  value={searchQuery}
                  onChange={(e) => setSearchQuery(e.target.value)}
                />
              </div>
              <div className="flex items-center gap-2">
                <button
                  onClick={fetchPayments}
                  className="px-3 py-2 border border-[#C8A45D/30] rounded-md shadow-sm hover:bg-[#C8A45D/20]/50 flex items-center gap-2 text-sm text-[#00717F] transition-colors"
                >
                  <RefreshCw className="h-4 w-4" />
                  Rafraîchir
                </button>
                <button
                  onClick={handleExportToExcel}
                  className="px-3 py-2 border border-[#C8A45D/30] rounded-md shadow-sm hover:bg-[#C8A45D/20]/50 flex items-center gap-2 text-sm text-[#00717F] transition-colors"
                >
                  <Download className="h-4 w-4" />
                  Exporter
                </button>
              </div>
            </div>
          </div>

          {error && (
            <div className="m-6 p-4 bg-red-50 border-l-4 border-red-500 flex items-center gap-3 rounded-r-md shadow-sm">
              <AlertCircle className="h-5 w-5 text-red-500 flex-shrink-0" />
              <p className="text-red-700">{error}</p>
            </div>
          )}

          {isLoading ? (
            <div className="flex justify-center items-center h-64">
              <div className="flex flex-col items-center gap-2">
                <Loader2 className="h-8 w-8 text-[#00717F] animate-spin" />
                <p className="text-gray-500">Chargement des paiements...</p>
              </div>
            </div>
          ) : filteredAndSortedPayments.length === 0 ? (
            <div className="flex flex-col justify-center items-center h-64 text-gray-500">
              <UserCircle className="h-16 w-16 text-gray-300 mb-2" />
              <p className="mb-2">Aucun enregistrement de paiement trouvé</p>
            </div>
          ) : (
            <div className="overflow-x-auto p-6">
              <table className="min-w-full divide-y divide-[#C8A45D/30]/50">
                <thead className="bg-[#F5F6FA]">
                  <tr>
                    <th
                      className="py-3.5 px-4 text-left text-xs font-medium text-[#00717F] uppercase tracking-wider cursor-pointer hover:bg-[#C8A45D/20]/50 transition-colors"
                      onClick={() => handleSort("internId.CFF")}
                    >
                      <div className="flex items-center gap-1">CFF {getSortIcon("internId.CFF")}</div>
                    </th>
                    <th
                      className="py-3.5 px-4 text-left text-xs font-medium text-[#00717F] uppercase tracking-wider cursor-pointer hover:bg-[#C8A45D/20]/50 transition-colors"
                      onClick={() => handleSort("internId.First_Name")}
                    >
                      <div className="flex items-center gap-1">Nom {getSortIcon("internId.First_Name")}</div>
                    </th>
                    <th
                      className="py-3.5 px-4 text-left text-xs font-medium text-[#00717F] uppercase tracking-wider cursor-pointer hover:bg-[#C8A45D/20]/50 transition-colors"
                      onClick={() => handleSort("academicYear")}
                    >
                      <div className="flex items-center gap-1">Année Académique {getSortIcon("academicYear")}</div>
                    </th>
                    <th className="py-3.5 px-4 text-left text-xs font-medium text-[#00717F] uppercase tracking-wider">
                      Statut de Paiement
                    </th>
                    <th className="py-3.5 px-4 text-left text-xs font-medium text-[#00717F] uppercase tracking-wider">
                      Total Payé
                    </th>
                    <th className="py-3.5 px-4 text-left text-xs font-medium text-[#00717F] uppercase tracking-wider">
                      Actions
                    </th>
                  </tr>
                </thead>
                <tbody className="bg-white divide-y divide-[#C8A45D/30]/30">
                  {filteredAndSortedPayments.map((payment) => {
                    const progress = getPaymentProgress(payment)
                    const status = getPaymentStatus(payment)
                    return (
                      <tr
                        key={payment._id}
                        className="hover:bg-[#F5F6FA]/30 transition-colors cursor-pointer"
                        onClick={() => openDetailsModal(payment)}
                      >
                        <td className="py-4 px-4 text-sm font-medium text-gray-900">{payment.internId.CFF}</td>
                        <td className="py-4 px-4">
                          <div className="flex items-center">
                            <div className="h-9 w-9 rounded-full bg-[#00717F]/10 flex items-center justify-center text-[#00717F] mr-3 shadow-sm">
                              <UserCircle className="h-5 w-5" />
                            </div>
                            <div className="text-sm font-medium text-gray-900">
                              {payment.internId.First_Name} {payment.internId.Last_Name}
                            </div>
                          </div>
                        </td>
                        <td className="py-4 px-4 text-sm text-gray-800">
                          <div className="flex items-center gap-2">
                            <Calendar className="h-4 w-4 text-[#00717F]/60" />
                            {payment.academicYear}
                          </div>
                        </td>
                        <td className="py-4 px-4 text-sm text-gray-800">
                          <div className="flex flex-col gap-1">
                            <div className="flex items-center justify-between">
                              <span className={`px-2 py-0.5 rounded-full text-xs font-medium ${status.color}`}>
                                {status.label}
                              </span>
                              <span className="text-xs text-gray-500">
                                {Object.keys(payment.payments).filter((month) => payment.payments[month] > 0).length}/
                                {months.length} mois
                              </span>
                            </div>
                            <div className="w-full bg-gray-200 rounded-full h-1.5">
                              <div className="bg-[#00717F] h-1.5 rounded-full" style={{ width: `${progress}%` }}></div>
                            </div>
                          </div>
                        </td>
                        <td className="py-4 px-4 text-sm font-medium">
                          <div className="flex items-center gap-2">
                            <DollarSign className="h-4 w-4 text-green-600" />
                            <span className="text-green-700">{payment.totalAmount} DH</span>
                          </div>
                        </td>
                        <td className="py-4 px-4 text-sm text-gray-800" onClick={(e) => e.stopPropagation()}>
                          <div className="flex items-center gap-2">
                            <button
                              onClick={() => openPaymentModal(payment)}
                              className="p-2 text-green-600 hover:bg-green-50 rounded-full transition-colors shadow-sm"
                              aria-label="Marquer le paiement"
                            >
                              <CheckCircle className="h-5 w-5" />
                            </button>
                            <button
                              onClick={() => openDetailsModal(payment)}
                              className="p-2 text-blue-600 hover:bg-blue-50 rounded-full transition-colors shadow-sm"
                              aria-label="Voir les détails"
                            >
                              <Info className="h-5 w-5" />
                            </button>
                          </div>
                        </td>
                      </tr>
                    )
                  })}
                </tbody>
              </table>
            </div>
          )}
        </div>
      </div>

      {isPaymentModalOpen && selectedPayment && (
        <div className="fixed inset-0 bg-black bg-opacity-50 flex items-center justify-center z-50">
          <div className="bg-white rounded-xl p-6 w-full max-w-md shadow-xl border border-[#C8A45D/30]">
            <div className="flex items-center justify-between mb-4">
              <h2 className="text-xl font-bold text-[#00717F]">Marquer le Paiement</h2>
              <button onClick={closePaymentModal} className="text-gray-500 hover:text-gray-700 transition-colors">
                <X className="h-5 w-5" />
              </button>
            </div>

            <div className="bg-[#F5F6FA]/50 p-4 rounded-lg mb-4">
              <div className="flex items-center gap-3">
                <div className="h-12 w-12 rounded-full bg-[#00717F]/10 flex items-center justify-center text-[#00717F] shadow-sm">
                  <UserCircle className="h-7 w-7" />
                </div>
                <div>
                  <h3 className="text-lg font-semibold text-gray-900">
                    {selectedPayment.internId.First_Name} {selectedPayment.internId.Last_Name}
                  </h3>
                  <p className="text-sm text-gray-500">CFF: {selectedPayment.internId.CFF}</p>
                </div>
              </div>
            </div>

            <div className="space-y-4">
              <div>
                <label className="block text-sm font-medium text-gray-700 mb-1">Montant du Paiement (DH)</label>
                <div className="relative">
                  <div className="absolute inset-y-0 left-0 pl-3 flex items-center pointer-events-none">
                    <DollarSign className="h-4 w-4 text-gray-400" />
                  </div>
                  <input
                    type="number"
                    value={paymentAmount}
                    onChange={(e) => setPaymentAmount(Number.parseInt(e.target.value) || 0)}
                    className="w-full border border-[#C8A45D/30] rounded-md p-2 pl-9 focus:outline-none focus:ring-2 focus:ring-[#00717F] focus:border-transparent"
                    placeholder="Entrer le montant"
                  />
                </div>
              </div>
              <div>
                <label className="block text-sm font-medium text-gray-700 mb-2">
                  Sélectionnez les mois à marquer comme payés
                </label>
                <div className="grid grid-cols-2 gap-3 mt-2 max-h-60 overflow-y-auto p-2 border border-[#C8A45D/30]/50 rounded-xl">
                  {months.map((month) => {
                    const isPaid = selectedPayment.payments[month] > 0
                    return (
                      <label
                        key={month}
                        className={`flex items-center gap-2 p-2 rounded-md ${isPaid ? "bg-green-50" : "hover:bg-gray-50"}`}
                      >
                        <input
                          type="checkbox"
                          checked={selectedMonths.includes(month)}
                          disabled={isPaid}
                          onChange={(e) => {
                            if (!isPaid) {
                              if (e.target.checked) {
                                setSelectedMonths([...selectedMonths, month])
                              } else {
                                setSelectedMonths(selectedMonths.filter((m) => m !== month))
                              }
                            }
                          }}
                          className={`rounded border-[#C8A45D/30] text-[#00717F] focus:ring-[#00717F] ${isPaid ? "opacity-50 cursor-not-allowed" : ""}`}
                        />
                        <div className="flex flex-col">
                          <span className={`${isPaid ? "text-green-700 font-medium" : "text-gray-700"}`}>
                            {monthTranslations[month]}
                          </span>
                          {isPaid && (
                            <span className="text-xs text-green-600 flex items-center gap-1">
                              <CheckCircle className="h-3 w-3" /> Payé ({selectedPayment.payments[month]} DH)
                            </span>
                          )}
                        </div>
                      </label>
                    )
                  })}
                </div>
              </div>
            </div>
            <div className="mt-6 flex justify-end gap-2">
              <button
                onClick={closePaymentModal}
                className="px-4 py-2 bg-gray-200 text-gray-700 rounded-md hover:bg-gray-300 transition-colors"
              >
                Annuler
              </button>
              <button
                onClick={handleConfirmPayment}
                className="px-4 py-2 bg-green-600 text-white rounded-md hover:bg-green-700 transition-colors flex items-center gap-2"
              >
                <CheckCircle className="h-4 w-4" />
                Confirmer le Paiement
              </button>
            </div>
          </div>
        </div>
      )}

      {isDetailsModalOpen && detailsPayment && (
        <div className="fixed inset-0 bg-black bg-opacity-50 flex items-center justify-center z-50">
          <div className="bg-white rounded-lg p-6 w-full max-w-2xl shadow-xl max-h-[80vh] overflow-y-auto border border-[#C8A45D/30]">
            <div className="flex items-center justify-between mb-4">
              <h2 className="text-xl font-bold text-[#00717F]">Détails des Paiements</h2>
              <button onClick={closeDetailsModal} className="text-gray-500 hover:text-gray-700 transition-colors">
                <X className="h-5 w-5" />
              </button>
            </div>

            <div className="bg-[#F5F6FA]/50 p-4 rounded-xl mb-4">
              <div className="flex items-center gap-3 mb-3">
                <div className="h-12 w-12 rounded-full bg-[#00717F]/10 flex items-center justify-center text-[#00717F] shadow-sm">
                  <UserCircle className="h-7 w-7" />
                </div>
                <div>
                  <h3 className="text-lg font-semibold text-gray-900">
                    {detailsPayment.internId.First_Name} {detailsPayment.internId.Last_Name}
                  </h3>
                  <p className="text-sm text-gray-500">CFF: {detailsPayment.internId.CFF}</p>
                </div>
              </div>

              <div className="grid grid-cols-1 md:grid-cols-3 gap-4 mt-2">
                <div className="bg-white p-3 rounded-xl shadow-sm border border-[#C8A45D/30]/30">
                  <div className="text-xs text-gray-500 uppercase">Année Académique</div>
                  <div className="text-lg font-medium text-[#00717F] flex items-center gap-2">
                    <Calendar className="h-4 w-4" />
                    {detailsPayment.academicYear}
                  </div>
                </div>

                <div className="bg-white p-3 rounded-xl shadow-sm border border-[#C8A45D/30]/30">
                  <div className="text-xs text-gray-500 uppercase">Total Payé</div>
                  <div className="text-lg font-medium text-green-700 flex items-center gap-2">
                    <DollarSign className="h-4 w-4" />
                    {detailsPayment.totalAmount} DH
                  </div>
                </div>

                <div className="bg-white p-3 rounded-xl shadow-sm border border-[#C8A45D/30]/30">
                  <div className="text-xs text-gray-500 uppercase">Mois Payés</div>
                  <div className="text-lg font-medium text-[#00717F] flex items-center gap-2">
                    <CheckCircle className="h-4 w-4" />
                    {Object.keys(detailsPayment.payments).filter((month) => detailsPayment.payments[month] > 0).length}/
                    {months.length}
                  </div>
                </div>
              </div>
            </div>

            <div className="mb-4">
              <h3 className="text-md font-semibold text-[#00717F] mb-2">Historique des Paiements</h3>
              <div className="border border-[#C8A45D/30]/50 rounded-xl overflow-hidden">
                <table className="min-w-full divide-y divide-[#C8A45D/30]/50">
                  <thead className="bg-[#F5F6FA]">
                    <tr>
                      <th className="py-2 px-4 text-left text-xs font-medium text-[#00717F] uppercase tracking-wider">
                        Mois
                      </th>
                      <th className="py-2 px-4 text-left text-xs font-medium text-[#00717F] uppercase tracking-wider">
                        Montant
                      </th>
                      <th className="py-2 px-4 text-left text-xs font-medium text-[#00717F] uppercase tracking-wider">
                        Statut
                      </th>
                    </tr>
                  </thead>
                  <tbody className="bg-white divide-y divide-[#C8A45D/30]/30">
                    {months.map((month) => {
                      const isPaid = detailsPayment.payments[month] > 0
                      return (
                        <tr key={month} className={isPaid ? "bg-green-50/50" : ""}>
                          <td className="py-2 px-4 text-sm text-gray-900">{monthTranslations[month]}</td>
                          <td className="py-2 px-4 text-sm text-gray-900">
                            {isPaid ? (
                              <span className="font-medium text-green-700">{detailsPayment.payments[month]} DH</span>
                            ) : (
                              <span className="text-gray-400">-</span>
                            )}
                          </td>
                          <td className="py-2 px-4 text-sm">
                            {isPaid ? (
                              <span className="inline-flex items-center px-2 py-0.5 rounded-full text-xs font-medium bg-green-100 text-green-800">
                                <CheckCircle className="h-3 w-3 mr-1" /> Payé
                              </span>
                            ) : (
                              <span className="inline-flex items-center px-2 py-0.5 rounded-full text-xs font-medium bg-gray-100 text-gray-800">
                                <Clock className="h-3 w-3 mr-1" /> En Attente
                              </span>
                            )}
                          </td>
                        </tr>
                      )
                    })}
                  </tbody>
                </table>
              </div>
            </div>

            {detailsPayment.observation && (
              <div className="mb-4">
                <h3 className="text-md font-semibold text-[#00717F] mb-2">Observation</h3>
                <div className="bg-gray-50 p-3 rounded-md border border-[#C8A45D/30]/30 text-gray-700">
                  {detailsPayment.observation}
                </div>
              </div>
            )}

            <div className="mt-6 pt-4 border-t border-[#C8A45D/30]/30 flex justify-between items-center">
              <div className="text-xs text-gray-500">
                <p>Créé: {new Date(detailsPayment.createdAt).toLocaleString("fr-FR")}</p>
                <p>Mis à jour: {new Date(detailsPayment.updatedAt).toLocaleString("fr-FR")}</p>
              </div>
              <div className="flex gap-2">
                <button
                  onClick={() => exportDetailsToPDF(detailsPayment)}
                  className="px-4 py-2 bg-blue-600 text-white rounded-md hover:bg-blue-700 transition-colors flex items-center gap-2"
                >
                  <Download className="h-4 w-4" />
                  Exporter en PDF
                </button>
                <button
                  onClick={closeDetailsModal}
                  className="px-4 py-2 bg-gray-200 text-gray-700 rounded-md hover:bg-gray-300 transition-colors"
                >
                  Fermer
                </button>
              </div>
            </div>
          </div>
        </div>
      )}
    </Layout>
  )
}
